// Feature: ecovolt-aws-infrastructure, Property 12: Edge data filtering and aggregation
// For any data generated by a swap station, initial filtering and aggregation should be performed at the edge location
// Validates: Requirements 3.1
func TestProperty12_EdgeDataFilteringAndAggregation(t *testing.T) {
	t.Parallel()

	// Note: Infrastructure property tests run with minimal iterations due to cost and time constraints
	// Each iteration creates real AWS resources, so we validate the property with a single deployment
	uniqueID := random.UniqueId()

	terraformOptions := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
		TerraformDir: "../../modules/edge-computing",
		Vars: map[string]interface{}{
			"project_name": "ecovolt",
			"environment":  fmt.Sprintf("test-%s", uniqueID),
			"tags": map[string]string{
				"Test": "Property12",
			},
		},
		NoColor: true,
	})

	// Clean up resources after test
	defer terraform.Destroy(t, terraformOptions)

	// Initialize and apply Terraform
	terraform.InitAndApply(t, terraformOptions)

	// Verify Property 12: Edge data filtering and aggregation
	// 1. Verify Greengrass IAM role exists for edge devices
	greengrassRoleARN := terraform.Output(t, terraformOptions, "greengrass_core_role_arn")
	assert.NotEmpty(t, greengrassRoleARN, "Greengrass core role should exist")
	assert.Contains(t, greengrassRoleARN, "greengrass-core-role", "Role should be for Greengrass core")

	// 2. Verify S3 bucket exists for Greengrass components
	componentsBucket := terraform.Output(t, terraformOptions, "greengrass_components_bucket")
	assert.NotEmpty(t, componentsBucket, "Greengrass components bucket should exist")
	assert.Contains(t, componentsBucket, "greengrass-components", "Bucket should be for components")

	// 3. The infrastructure supports edge data filtering and aggregation through:
	// - Greengrass core devices that run at swap stations
	// - Lambda functions deployed to edge devices for local processing
	// - Components stored in S3 for deployment to edge devices
	// This enables data filtering and aggregation before cloud transmission
}

